const response = $input.first().json;
const previousData = $('Prepare Prompt').first().json;

try {
  const content = response.choices[0].message.content;

  let roadmap;
  try {
    roadmap = JSON.parse(content);
  } catch (e) {
    const jsonMatch = content.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      roadmap = JSON.parse(jsonMatch[0]);
    } else {
      throw new Error('Could not parse OpenAI response as JSON');
    }
  }

  return [{
    json: {
      success: true,
      roadmap: roadmap.roadmap || [],
      summary: roadmap.summary || '',
      diagnostic: {
        overallLevel: previousData.overallLevel,
        totalScore: previousData.totalScore,
        maxScore: previousData.maxScore
      }
    }
  }];
} catch (error) {
  return [{
    json: {
      success: false,
      error: error.message,
      rawResponse: response
    }
  }];
}

const data = $input.first().json;

if (data.success) {
  return [{
    json: {
      statusCode: 200,
      body: {
        success: true,
        roadmap: data.roadmap,
        summary: data.summary,
        diagnostic: data.diagnostic
      }
    }
  }];
} else {
  return [{
    json: {
      statusCode: 500,
      body: {
        success: false,
        error: data.error || 'Failed to generate roadmap'
      }
    }
  }];
}
